import os, sys, pty, time, select, fcntl, termios, struct, signal, re

def run(args, keys, cwd=None, env=None, rows=24, cols=80, delay=0.30, exe="/workspace/executable",
        final_wait=0.7, bg=b"\x1b]11;rgb:0000/0000/0000\x1b\\", answer=True):
    pid, fd = pty.fork()
    if pid == 0:
        if cwd: os.chdir(cwd)
        e = dict(os.environ)
        e["TERM"] = "xterm-256color"
        for k in ("WALK_STATUS_BAR","WALK_MAIN_COLOR","WALK_ICONS","WALK_EDITOR","EDITOR","WALK_OPEN_WITH","WALK_REMOVE_CMD"):
            e.pop(k, None)
        e["LINES"]=str(rows); e["COLUMNS"]=str(cols)
        if env: e.update(env)
        os.execve(exe, [exe]+args, e)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    out = []
    state = {"bg":False, "cpr":False}
    def pump(t):
        end = time.time()+t
        while time.time() < end:
            r,_,_ = select.select([fd], [], [], 0.02)
            if r:
                try: d = os.read(fd, 65536)
                except OSError: return False
                if not d: return False
                out.append(d)
                if answer:
                    if b"\x1b]11;?" in d and not state["bg"]:
                        state["bg"]=True; os.write(fd, bg)
                    if b"[6n" in d and not state["cpr"]:
                        state["cpr"]=True; os.write(fd, b"\x1b[1;1R")
        return True
    pump(delay)
    for k in keys:
        if isinstance(k, float):
            pump(k); continue
        try: os.write(fd, k.encode() if isinstance(k,str) else k)
        except OSError: break
        if not pump(delay): break
    pump(final_wait)
    try: os.kill(pid, signal.SIGKILL)
    except Exception: pass
    try: _, status = os.waitpid(pid, 0)
    except Exception: status = -1
    try: os.close(fd)
    except Exception: pass
    return b"".join(out), status

def resize(fd, rows, cols):
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
