import subprocess, time, os, shlex, sys

SESS = "walkobs"

def sh(*a, check=True):
    return subprocess.run(a, capture_output=True, text=True)

def kill():
    sh("tmux", "kill-session", "-t", SESS)

def start(args=(), cwd="/tmp/sandbox", env=None, rows=24, cols=80, exe="/workspace/executable", sleep=0.8):
    kill()
    envp = ""
    base = {"TERM":"xterm-256color"}
    if env: base.update(env)
    for k,v in base.items():
        envp += "%s=%s " % (k, shlex.quote(v))
    cmd = envp + shlex.quote(exe) + " " + " ".join(shlex.quote(a) for a in args)
    full = "cd %s && %s; echo __EXIT:$?__; cat /tmp/h/walk_out 2>/dev/null; sleep 999" % (shlex.quote(cwd), cmd)
    sh("tmux", "new-session", "-d", "-s", SESS, "-x", str(cols), "-y", str(rows), "sh", "-c", full)
    time.sleep(sleep)

def keys(*ks, sleep=0.45):
    for k in ks:
        sh("tmux", "send-keys", "-t", SESS, *( [k] if not k.startswith("HEX:") else ["-H"]+k[4:].split(",") ))
        time.sleep(sleep)

def lit(s, sleep=0.45):
    sh("tmux", "send-keys", "-t", SESS, "-l", s)
    time.sleep(sleep)

def cap(esc=False, rows=None):
    a = ["tmux","capture-pane","-p","-t",SESS]
    if esc: a.append("-e")
    r = sh(*a)
    return r.stdout.rstrip("\n")

def show(esc=False):
    print(cap(esc))

def resize(rows, cols):
    sh("tmux","resize-window","-t",SESS,"-x",str(cols),"-y",str(rows))
    time.sleep(0.5)
